import React from 'react';
import { motion, useScroll, useTransform } from 'framer-motion';

function Hero() {
    const { scrollY } = useScroll();

    // Parallax / Kinetic effect for background text
    const textX = useTransform(scrollY, [0, 500], [0, -200]);

    return (
        <section className="hero-section">
            <motion.div
                style={{ x: textX }}
                className="kinetic-bg-text"
            >
                CREATIVE SOFTWARE
            </motion.div>

            <div className="hero-content">
                <motion.span
                    initial={{ opacity: 0, x: -20 }}
                    animate={{ opacity: 1, x: 0 }}
                    className="hero-subtitle"
                >
                    Personal Tech Blog
                </motion.span>

                <h1 className="hero-title">
                    Insights for modern software teams.<br />
                    <span className="typing-text">Engineered for clarity.</span>
                </h1>

                <motion.div
                    initial={{ scaleX: 0 }}
                    animate={{ scaleX: 1 }}
                    transition={{ duration: 1, delay: 0.5 }}
                    className="hero-divider"
                />

                <p className="hero-description">
                    Fresh thinking on cloud strategy, product architecture, and developer workflows.
                    Practical guidance for builders who want polished systems and fast delivery.
                </p>

                <div className="hero-cta">
                    <a href="#blog" className="cta-primary">Read latest posts</a>
                    <a href="#contact" className="cta-secondary">Work with me</a>
                </div>

                {/* Abstract SVG Blob */}
                <div className="abstract-blob">
                    <svg viewBox="0 0 200 200" xmlns="http://www.w3.org/2000/svg">
                        <motion.path
                            fill="var(--accent-glow)"
                            animate={{
                                d: [
                                    "M44.7,-76.4C58.2,-69.3,69.5,-57.4,77.3,-43.3C85.2,-29.2,89.5,-12.9,88.7,3.1C87.9,19.1,82,34.8,72.6,48.4C63.2,62,50.3,73.5,35.7,79.4C21.1,85.2,4.8,85.4,-11.5,82.4C-27.8,79.4,-44.1,73.2,-57.1,62.8C-70.1,52.4,-79.8,37.8,-83.9,21.8C-88,5.8,-86.5,-11.6,-80.4,-27C-74.3,-42.4,-63.6,-55.8,-50.7,-63.3C-37.8,-70.8,-22.7,-72.4,-7.3,-71.2C8.1,-70,23.5,-66.1,44.7,-76.4Z",
                                    "M44.9,-73.9C57.4,-67.3,67.6,-57.3,75.8,-44.8C84,-32.3,90.1,-17.3,88.9,-1.5C87.7,14.4,79.2,28.7,68.3,39.7C57.4,50.7,44,58.4,29.3,64C14.6,69.7,-1.6,73.4,-16.2,71.3C-30.7,69.2,-43.6,61.2,-55.1,50.4C-66.6,39.6,-76.8,26,-82.7,10.7C-88.6,-4.6,-90.2,-22.5,-83.9,-36.8C-77.6,-51.2,-63.5,-61.9,-48,-67.7C-32.4,-73.6,-16.2,-74.7,-0.3,-74.4C15.7,-74.1,31.4,-72.4,44.9,-73.9Z"
                                ]
                            }}
                            transition={{ repeat: Infinity, duration: 8, ease: "easeInOut" }}
                            transform="translate(100 100)"
                        />
                    </svg>
                </div>
            </div>
        </section>
    );
}

export default Hero;
